const CACHE='carte-claire-v5-safari-compatible';const ASSETS=['./','./index.html','./style.css?v=20261109-2','./app.js?v=20261109-2','./engine.mjs?v=20261109-2','./provenance.mjs?v=20261109-2','./snapshot.mjs?v=20261109-2','./manifest.webmanifest','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(url,{cache:'reload'})))));self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('carte-claire-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
